mapper.insert:
INSERT INTO email_draft_attachments (email_draft_id, evidence_id)
SELECT #{draftId}, id
FROM case_evidences
WHERE id = #{evidenceId}
  AND case_id = #{caseId}

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM email_drafts d
    JOIN cases c ON c.id = d.case_id
    JOIN users u ON u.id = c.user_id
    WHERE d.id = #{draftId}
      AND u.login_id = #{loginId}
      AND u.users_status = 'ACTIVE'
      AND u.deleted_at IS NULL
)
